    const revealedPois = getRunPois(s.hiddenBoss, detourPois)
      .filter(p => !(p.kind === 'boss' && s.hiddenBossDefeated))
      // 裏ボスが実際に出ている間は、巣のPOI矢印を下げてボスマークへ一本化する(同じ座標=下の .map で
